export async function downloadFile(s3Url: string | null | undefined, fileName = 'file.csv') {
  if (!s3Url) {
    showToastError('Source link not found');
    return;
  }

  /*
      TODO: use fetch after s3 cors configuration
      const response = await fetch(s3Url);
      const blob = await response.blob();
      const url = URL.createObjectURL(blob); 
      URL.revokeObjectURL(url);
    */
  const link = document.createElement('a');
  link.href = s3Url;
  link.download = fileName;
  link.click();
}
